        public static List<string> GetCompanies()
        {
            return _jobs.Select(j => j.CompanyName ?? string.Empty).Where(s => !string.IsNullOrWhiteSpace(s)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(s => s).ToList();
        }

        public static List<Job> GetPaged(string title, string location, string type, int page, int pageSize, out int total)
        {
            var q = _jobs.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(title))
                q = q.Where(j => (j.Title ?? string.Empty).IndexOf(title, StringComparison.OrdinalIgnoreCase) >= 0);

            if (!string.IsNullOrWhiteSpace(location))
                q = q.Where(j => (j.Location ?? string.Empty).IndexOf(location, StringComparison.OrdinalIgnoreCase) >= 0);

            if (!string.IsNullOrWhiteSpace(type))
                q = q.Where(j => (j.Type ?? string.Empty).IndexOf(type, StringComparison.OrdinalIgnoreCase) >= 0);

            var filtered = q.ToList();
            total = filtered.Count;

            // simple paging
            int skip = Math.Max(0, (page - 1) * pageSize);
            return filtered.Skip(skip).Take(pageSize).ToList();
        }

        internal static void SaveSearch(string username, SavedSearch search)
        {
            if (string.IsNullOrWhiteSpace(username) || search == null) return;
            List<SavedSearch> list;
            if (!_savedSearchesByUser.TryGetValue(username, out list))
            {
                list = new List<SavedSearch>();
                _savedSearchesByUser[username] = list;
            }
            search.SavedSearchId = _nextSavedSearchId++;
            list.Add(search);
        }

        internal static void CreateAlert(string username, JobAlert alert)
        {
            if (string.IsNullOrWhiteSpace(username) || alert == null) return;
            List<JobAlert> list;
            if (!_alertsByUser.TryGetValue(username, out list))
            {
                list = new List<JobAlert>();
                _alertsByUser[username] = list;
            }
            alert.JobAlertId = _nextAlertId++;
            list.Add(alert);
        }

        internal static List<SavedSearch> GetSavedSearches(string username)
        {
            if (string.IsNullOrWhiteSpace(username)) return new List<SavedSearch>();
            List<SavedSearch> list;
            if (!_savedSearchesByUser.TryGetValue(username, out list)) return new List<SavedSearch>();
            return list.ToList();
        }

        public static void DeleteSavedSearch(int id, string username)
        {
            if (string.IsNullOrWhiteSpace(username)) return;
            List<SavedSearch> list;
            if (!_savedSearchesByUser.TryGetValue(username, out list)) return;
            var s = list.Find(x => x.SavedSearchId == id);
            if (s != null) list.Remove(s);
        }
    }

